use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn bitwise_and_spec(a: Seq<u8>, b: Seq<u8>) -> Seq<u8>
    requires
        a.len() == b.len(),
    ensures
        |result| {
            result.len() == a.len() &&
            forall|i: int| 0 <= i < a.len() ==> result[i] == (a[i] & b[i])
        },
{
    Seq::new(a.len(), |i: int| a[i] & b[i])
}

fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires
        a.len() == b.len(),
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == (a[i] & b[i]),
{
    // Ensure both vectors have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");
    
    // Create a new vector to store the results
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through both vectors simultaneously
    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == (a[j] & b[j]),
        decreases a.len() - i,
    {
        result.push(a[i] & b[i]);
        i = i + 1;
    }
    
    result
}

}
